 "width": "100%",
 "shadow": false,
 "borderSize": 0,
 "scrollBarVisible": "rollOver",
 "minWidth": 1,
 "scrollBarMargin": 2,
 "paddingRight": 0,
 "paddingLeft": 0,
 "height": "100%",
 "paddingTop": 0,
 "backgroundOpacity": 0,
 "html": "<div style=\"text-align:left; color:#000; \"><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#218abb;font-size:3.58vh;font-family:'Antonio';\"><B>AYDIN </B></SPAN><SPAN STYLE=\"color:#142645;font-size:3.58vh;font-family:'Antonio';\"><B>SATIYOR</B></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#999999;font-size:1.72vh;\">Ayd\u0131n Sat\u0131yor; gayrimenkul sekt\u00f6r\u00fcndeki hantal, \u015feffaf olmayan ve eski nesil al\u0131m-sat\u0131m s\u00fcre\u00e7lerini k\u00f6k\u00fcnden de\u011fi\u015ftirmek amac\u0131yla kurulmu\u015f yeni nesil bir gayrimenkul dan\u0131\u015fmanl\u0131k firmas\u0131d\u0131r. Klasik emlak\u00e7\u0131l\u0131k anlay\u0131\u015f\u0131n\u0131n aksine; bir m\u00fclk\u00fc sadece listelere ekleyip beklemeyi reddediyor, her portf\u00f6y\u00fc kendi dinamiklerine uygun modern sunum teknikleri ve stratejik pazarlama planlar\u0131ylay\u00f6netiyoruz. Al\u0131m, sat\u0131m ve kiralama s\u00fcre\u00e7lerinde zaman\u0131n ve do\u011fru fiyatlaman\u0131n kritik \u00f6nemini biliyor; s\u00fcreci ba\u015f\u0131ndan sonuna kadar veriyle, h\u0131zla ve mutlak \u015feffafl\u0131kla y\u00fcr\u00fct\u00fcyoruz.</SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:3.58vh;font-family:'Antonio';\"><B>Adres:</B></SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:1.72vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.14vh;font-family:Arial, Helvetica, sans-serif;\"/></p><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:1.72vh;font-family:'Open Sans Semibold';\">Web: www.aydinsehircilik.com/</SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:1.72vh;font-family:'Open Sans Semibold';\">Tlf.:</SPAN><SPAN STYLE=\"color:#999999;font-size:1.72vh;font-family:'Open Sans Semibold';\"> 0 (546) 547 11 52 Ali eren</SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"font-size:1.72vh;font-family:'Open Sans Semibold';\">Addres:</SPAN><SPAN STYLE=\"color:#999999;font-size:1.72vh;font-family:'Open Sans Semibold';\"> Mengene Mah. Fetih Cad. 340/A Karatay/ Konya</SPAN></SPAN></DIV><p STYLE=\"margin:0; line-height:1.72vh;\"><BR STYLE=\"letter-spacing:0vh;color:#000000;font-size:1.14vh;font-family:Arial, Helvetica, sans-serif;\"/></p></div>",
