 "html": "<div style=\"text-align:left; color:#000; \"><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:2vh;font-family:'Antonio';\"><B> V\u0130LLAMIZIN BULUNDU\u011eU MEVK\u0130 ;</B></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:2.15vh;\"> </SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:2.15vh;\">  \u2022 </SPAN><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;\"> </SPAN><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;font-family:'Antonio';\"><B>KONYA LALEBAH\u00c7E MAHALLES\u0130NDE </B></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;\">  \u2022  </SPAN><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;font-family:'Antonio';\"><B>HARMANCIK CADDES\u0130NE YAKIN</B></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;\">  \u2022  </SPAN><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;font-family:'Antonio';\"><B>HATIP CADDES\u0130NE 1 PARSEL \u0130\u00c7ER\u0130DE</B></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;\">  \u2022  </SPAN><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;font-family:'Antonio';\"><B>HARMANCIK KAPALI PAZARININ ARKASINDA</B></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;\">  \u2022  </SPAN><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;font-family:'Antonio';\"><B>ANTALYA \u00c7EVRE YOLUNA YAKIN</B></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;\">  \u2022  </SPAN><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;font-family:'Antonio';\"><B>KONYANIN EN TEM\u0130Z HAVASININ OLDU\u011eU LALEBAH\u00c7EDED\u0130R.</B></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;\">  \u2022  </SPAN><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;font-family:'Antonio';\"><B>OKUL,ECZANE,SA\u011eLIK OCA\u011eI,MARKET YAKIN</B></SPAN></SPAN></DIV><DIV STYLE=\"text-align:left;\"><SPAN STYLE=\"letter-spacing:0vh;color:#000000;font-family:Arial, Helvetica, sans-serif;\"><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;\">  \u2022  </SPAN><SPAN STYLE=\"color:#99bb1b;font-size:1.86vh;font-family:'Antonio';\"><B>ULA\u015eIMI KOLAY </B></SPAN></SPAN></DIV></div>",
